/**
 * List Items are the components that make up the children for Lists.
 *
 * - {@link https://livingdesign.walmart.com/components/list/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/list/react/ React documentation}
 *
 * ### Content
 *
 * The List Item accepts content through the `children` props:
 *
 * ```tsx
 * <ListItem>Content</ListItem>
 * ```
 *
 * ### Leading
 *
 * The List Item accepts optional leading content through the `leading` prop:
 *
 * ```tsx
 * <ListItem leading={<LeadingIcon />}>
 *   Content
 * </ListItem>
 * ```
 *
 * ### Title
 *
 * The List Item accepts an optional title through the `title` prop:
 *
 * ```tsx
 * <ListItem title="Title">
 *   Content
 * </ListItem>
 * ```
 *
 * ### Trailing
 *
 * The List Item accepts optional trailing content through the `trailing` prop:
 *
 * ```tsx
 * <ListItem trailing={<TrailingIcon />}>
 *   Content
 * </ListItem>
 * ```
 */
export declare const ListItem: React.FunctionComponent<ListItemProps>;
